  function pokerGacEsc(s) {
    return String(s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }
  function pokerGacTrimUrlTrailing(s) {
    return String(s || "").replace(/[),.;:!?]+$/g, "");
  }
