function saveDailyPredictionStorage(state) {
  try {
    localStorage.setItem("poker_daily_prediction_state", JSON.stringify(state));
  } catch (e) {}
}

function getTodayKey() {
  var d = new Date();
  var y = d.getFullYear();
  var m = String(d.getMonth() + 1).padStart(2, "0");
  var day = String(d.getDate()).padStart(2, "0");
  return y + "-" + m + "-" + day;
}

function ensureTodayPredictionState() {
  var key = getTodayKey();
  var state = getDailyPredictionStorage();
  var index;
  if (state && state.date === key && typeof state.index === "number") {
    index = state.index;
  } else {
    var prevIndex = state && typeof state.index === "number" ? state.index : null;
    if (!POKER_DAILY_PREDICTIONS.length) {
      index = 0;
    } else {
      index = Math.floor(Math.random() * POKER_DAILY_PREDICTIONS.length);
      if (POKER_DAILY_PREDICTIONS.length > 1 && prevIndex != null && index === prevIndex) {
        index = (index + 1) % POKER_DAILY_PREDICTIONS.length;
      }
    }
    state = { date: key, index: index, read: false };
    saveDailyPredictionStorage(state);
  }
  return state;
}

function getPokerDailyPredictionForToday() {
  var state = ensureTodayPredictionState();
  return POKER_DAILY_PREDICTIONS[state.index] || "";
}

function markDailyPredictionRead() {
  var state = ensureTodayPredictionState();
  if (!state.read) {
    state.read = true;
    saveDailyPredictionStorage(state);
  }
}

function updateDailyPredictionBadge() {
  var badge = document.getElementById("dailyPredictionBadge");
  var preview = document.getElementById("dailyPredictionPreview");
  if (!badge) return;
  var state = ensureTodayPredictionState();
  var unread = !state.read;
  badge.classList.toggle("feature__badge--hidden", !unread);
  badge.setAttribute("aria-hidden", unread ? "false" : "true");
  if (preview && !unread) {
    preview.textContent = "Совет на сегодня уже открыт";
  }
}

var dailyPredictionTimerId = null;

function formatMsToHms(ms) {
  if (ms < 0) ms = 0;
  var totalSec = Math.floor(ms / 1000);
  var h = Math.floor(totalSec / 3600);
  var m = Math.floor((totalSec % 3600) / 60);
  var s = totalSec % 60;
  function pad(n) { return n < 10 ? "0" + n : String(n); }
  return pad(h) + ":" + pad(m) + ":" + pad(s);
}

function updateDailyPredictionTimer() {
  var el = document.getElementById("dailyPredictionTimer");
  if (!el) return;
  var now = new Date();
  var tomorrow = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1, 0, 0, 0, 0);
  var diff = tomorrow - now;
  el.textContent = "Следующее через " + formatMsToHms(diff);
}

function startDailyPredictionTimer() {
  updateDailyPredictionTimer();
  if (dailyPredictionTimerId) clearInterval(dailyPredictionTimerId);
  dailyPredictionTimerId = setInterval(updateDailyPredictionTimer, 1000);
}

function stopDailyPredictionTimer() {
  if (dailyPredictionTimerId) {
    clearInterval(dailyPredictionTimerId);
    dailyPredictionTimerId = null;
  }
}

function playClickSound() {
  try {
    var Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    var ctx = window.__clickAudioCtx;
    if (!ctx) ctx = window.__clickAudioCtx = new Ctx();
    if (ctx.state === "suspended") ctx.resume();
    var now = ctx.currentTime;
    var osc = ctx.createOscillator();
    var gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.type = "sine";
    osc.frequency.setValueAtTime(180, now);
    osc.frequency.exponentialRampToValueAtTime(80, now + 0.03);
    gain.gain.setValueAtTime(0.06, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.05);
    osc.start(now);
    osc.stop(now + 0.05);
  } catch (err) {}
}

// PWA: короткий звук при новых сообщениях в чате.
function pokerReadChatMessageSoundEnabled() {
  try {
    var v = localStorage.getItem("poker_chat_msg_sound");
    if (v === null) return true;
    return v === "1" || String(v).toLowerCase() === "true" || String(v).toLowerCase() === "on";
  } catch (e) {
    // В приватных режимах/ограничениях localStorage может падать — тогда считаем, что звук включен.
    return true;
  }
}
function pokerPlayChatMessageNotificationSound() {
  try {
    var Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    var ctx = window.__msgAudioCtx;
    if (!ctx) ctx = window.__msgAudioCtx = new Ctx();
    if (ctx.state === "suspended") ctx.resume();
    var now = ctx.currentTime;
    // Два быстрых тона: коротко и заметно, но без долгого "пищания".
    var mkTone = function (freq, t0, dur, g0) {
      var osc = ctx.createOscillator();
      var gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.type = "sine";
      osc.frequency.setValueAtTime(freq, t0);
      gain.gain.setValueAtTime(g0, t0);
      gain.gain.exponentialRampToValueAtTime(0.001, t0 + dur);
      osc.start(t0);
      osc.stop(t0 + dur);
    };
    mkTone(740, now, 0.06, 0.05);
    mkTone(520, now + 0.08, 0.07, 0.04);
  } catch (err) {}
}

function tryChillRadioPlay() {
  var mode = localStorage.getItem("chill_radio_mode") || "";
  if (mode !== "chill" && mode !== "lounge" && mode !== "90s" && mode !== "radio7") return;
  var radio = document.getElementById("chillRadio");
  if (!radio) return;
  var urls = { chill: "https://ice2.somafm.com/groovesalad-128-mp3", lounge: "https://ice5.somafm.com/illstreet-128-mp3", "90s": "https://nostalgiafm.hostingradio.ru:8014/nostalgiafm.mp3", radio7: "https://stream.rcast.net/263744" };
  if (urls[mode]) radio.src = urls[mode];
  var p = radio.play();
  if (p && typeof p.then === "function") p.catch(function () {});
}

/** Состояние верификации Telegram для доступа к чату (см. __pokerTelegramAuth в initTelegramAuth) */
function getPokerChatTelegramAuthState() {
  try {
    var a = window.__pokerTelegramAuth;
    if (!a || !a.status) return "pending";
    if (a.status === "verified" || a.status === "dev_skip") {
      return a.user != null && a.user.id != null ? "ok" : "blocked";
    }
    if (a.status === "verifying" || a.status === "unknown") return "pending";
    return "blocked";
  } catch (e) {
    return "pending";
  }
}

/** Сообщение при попытке писать в чат без входа (браузер / PWA). */
var POKER_CHAT_NEED_AUTH_PWA_MSG =
  "Чтобы общаться в чатах, сначала авторизуйтесь.\n1. Добавьте ярлык на экран «Домой» (из Safari или Google Chrome).\n2. Зайдите с ярлыка и авторизуйтесь.";

function pokerNotifyChatVerificationRequired() {
  var msg = isTelegramWebApp()
    ? "Чтобы общаться в чатах, сначала войдите: откройте Mini App из бота Telegram."
    : POKER_CHAT_NEED_AUTH_PWA_MSG;
  var w = window.Telegram && window.Telegram.WebApp;
  if (w && w.showAlert) w.showAlert(msg);
  else if (typeof alert === "function") alert(msg);
}

function pokerNotifyChatAuthPending() {
  var msg = "Выполняется проверка входа через Telegram… Повторите через несколько секунд.";
  var w = window.Telegram && window.Telegram.WebApp;
  if (w && w.showAlert) w.showAlert(msg);
  else if (typeof alert === "function") alert(msg);
}

/** false — прервать действие в чате (показано уведомление) */
function pokerEnsureChatTelegramVerified() {
  var st = getPokerChatTelegramAuthState();
  if (st === "pending") {
    pokerNotifyChatAuthPending();
    return false;
  }
  if (st !== "ok") {
    pokerNotifyChatVerificationRequired();
    return false;
  }
  return true;
}

