    var inLeague2 = forcedLeague === 2 || (forcedLeague !== forcedLeague && buyin >= 100 && buyin < 500);
    var include = (leagueNum === 1 && inLeague1) || (leagueNum === 2 && inLeague2);
    if (!include) continue;
