            data.iCanChangeGroupAvatar === true || data.iCanChangeGroupAvatar === false
              ? !!data.iCanChangeGroupAvatar
              : !!(data.isAdmin || data.iAmGroupCreator);
          syncConvGroupAvatarEditUi();
