    var urlBtn = t.closest && t.closest(".tracking-links-admin__url-copy-btn");
    if (urlBtn) {
      var urlToCopy = urlBtn.getAttribute("data-url");
      if (urlToCopy) copyUrlWithFeedback(urlToCopy);
      return;
    }
    var btn = t.closest && t.closest("[data-tracking-who]");
    if (!btn) return;
